// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

import {PortalHub} from "@integrations/outland/portals/PortalHub.sol";
import {InfiniFiGatewayV3} from "@gateway/InfiniFiGatewayV3.sol";

/// @notice Gateway to interact with the InfiniFi protocol
/// This version implements L1 -> L2 bridging of iUSD or siUSD to supported L2 chains.
/// @dev Requires BRIDGE_INITIATOR role to initiate bridging transactions.
contract InfiniFiGatewayV4 is InfiniFiGatewayV3 {
    using SafeERC20 for ERC20;

    error InsufficientBridgeFee(uint256 required, uint256 provided);

    /// @notice Bridges iUSD or siUSD to a supported L2 chain
    /// @dev Requires BRIDGE_INITIATOR on this contract and portalHub registered in the address registry
    /// @param _targetChainId Destination outpost chain ID
    /// @param _token iUSD or siUSD token address on L1
    /// @param _amount Amount of tokens to bridge
    /// @param _recipient Recipient on the destination chain
    /// @param _connector Authorized connector that relays the cross-chain message
    function bridge(
        uint256 _targetChainId,
        address _token,
        uint256 _amount,
        address _recipient,
        address payable _connector
    ) external payable whenNotPaused nonReentrant {
        PortalHub portalHub = PortalHub(getAddress("portalHub"));
        uint256 messageFee = portalHub.getBridgeMessageFee(_targetChainId, _connector);
        require(msg.value >= messageFee, InsufficientBridgeFee(messageFee, msg.value));

        ERC20(_token).safeTransferFrom(msg.sender, address(this), _amount);
        ERC20(_token).forceApprove(address(portalHub), _amount);
        portalHub.bridge{value: msg.value}(_targetChainId, _token, _amount, _recipient, _connector);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

import {GovernanceToken} from "@tokens/GovernanceToken.sol";
import {LockingController} from "@locking/LockingController.sol";
import {InfiniFiGatewayV2} from "@gateway/InfiniFiGatewayV2.sol";
import {MigrationController} from "@funding/MigrationController.sol";

/// @notice Gateway to interact with the InfiniFi protocol
contract InfiniFiGatewayV3 is InfiniFiGatewayV2 {
    using SafeERC20 for ERC20;

    function migrate(address _farm, address _token, uint256 _amount, uint32 _unwindingEpochs, uint256 _minIusdReceived)
        external
        whenNotPaused
        nonReentrant
        returns (uint256)
    {
        ERC20 token = ERC20(_token);
        MigrationController migrationController = MigrationController(getAddress("migrationController"));

        token.safeTransferFrom(msg.sender, address(this), _amount);
        token.approve(address(migrationController), _amount);
        uint256 iusdReceived = migrationController.migrate(msg.sender, _farm, _token, _amount, _unwindingEpochs);
        require(iusdReceived >= _minIusdReceived, MinAssetsOutError(_minIusdReceived, iusdReceived));
        return iusdReceived;
    }

    function lockInfi(uint256 _amount, uint32 _unwindingEpochs) external whenNotPaused nonReentrant {
        GovernanceToken infi = GovernanceToken(getAddress("governanceToken"));
        LockingController locker = LockingController(getAddress("governanceLockingController"));

        // forge-lint: disable-next-line(erc20-unchecked-transfer)
        infi.transferFrom(msg.sender, address(this), _amount);
        infi.approve(address(locker), _amount);
        locker.createPosition(_amount, _unwindingEpochs, msg.sender);
    }

    function startInfiWithdrawal(uint256 _shares, uint32 _unwindingEpochs) external whenNotPaused nonReentrant {
        LockingController locker = LockingController(getAddress("governanceLockingController"));
        GovernanceToken linfi = GovernanceToken(locker.shareToken(_unwindingEpochs));

        // forge-lint: disable-next-line(erc20-unchecked-transfer)
        linfi.transferFrom(msg.sender, address(this), _shares);
        linfi.approve(address(locker), _shares);
        locker.startUnwinding(_shares, _unwindingEpochs, msg.sender);
    }

    function increaseInfiWithdrawalPeriod(uint32 _oldUnwindingEpochs, uint32 _newUnwindingEpochs, uint256 _shares)
        external
        whenNotPaused
        nonReentrant
    {
        LockingController locker = LockingController(getAddress("governanceLockingController"));
        GovernanceToken linfi = GovernanceToken(locker.shareToken(_oldUnwindingEpochs));

        // forge-lint: disable-next-line(erc20-unchecked-transfer)
        linfi.transferFrom(msg.sender, address(this), _shares);
        linfi.approve(address(locker), _shares);
        locker.increaseUnwindingEpochs(_shares, _oldUnwindingEpochs, _newUnwindingEpochs, msg.sender);
    }

    function cancelInfiWithdrawal(uint256 _unwindingTimestamp, uint32 _newUnwindingEpochs)
        external
        whenNotPaused
        nonReentrant
    {
        LockingController(getAddress("governanceLockingController"))
            .cancelUnwinding(msg.sender, _unwindingTimestamp, _newUnwindingEpochs);
    }

    function completeInfiWithdrawal(address _user, uint256 _unwindingTimestamp) external whenNotPaused nonReentrant {
        LockingController(getAddress("governanceLockingController")).withdraw(_user, _unwindingTimestamp);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {FixedPointMathLib} from "@solmate/src/utils/FixedPointMathLib.sol";

import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReentrancyGuardTransient} from "@openzeppelin/contracts/utils/ReentrancyGuardTransient.sol";

import {CoreRoles} from "@libraries/CoreRoles.sol";
import {StakedToken} from "@tokens/StakedToken.sol";
import {ReceiptToken} from "@tokens/ReceiptToken.sol";
import {CoreControlled} from "@core/CoreControlled.sol";
import {MintController} from "@funding/MintController.sol";
import {YieldSharingV2} from "@finance/YieldSharingV2.sol";
import {RedeemController} from "@funding/RedeemController.sol";
import {AllocationVoting} from "@governance/AllocationVoting.sol";
import {LockingController} from "@locking/LockingController.sol";
import {LockedPositionToken} from "@tokens/LockedPositionToken.sol";

/// @notice Gateway to interact with the InfiniFi protocol
contract InfiniFiGatewayV2 is CoreControlled, ReentrancyGuardTransient {
    using SafeERC20 for ERC20;
    using FixedPointMathLib for uint256;

    /// @notice error thrown when there are pending losses unapplied
    /// if you observe this error as a user, call YieldSharing.accrue() before
    /// attempting a withdrawal from the vault.
    error PendingLossesUnapplied();

    /// @notice error thrown when a swap fails
    error SwapFailed();
    error InvalidZapFee();
    error InvalidZapRouter();
    error MinAssetsOutError(uint256 min, uint256 actual);

    event AddressSet(uint256 timestamp, string indexed name, address _address);
    event ZapFeeSet(uint256 timestamp, uint256 zapFee);
    event ZapIn(uint256 timestamp, address indexed user, address indexed token, uint256 amount, uint256 receiptTokens);
    event SetEnabledRouter(uint256 timestamp, address router, bool enabled);

    /// @notice address registry of the gateway
    mapping(bytes32 => address) public addresses;

    /// @notice Mapping of routers that can be used to zap
    mapping(address => bool) public enabledRouters;

    /// @notice fee charged for zaps, as a percentage with 18 decimals
    uint256 public zapFee;

    constructor() CoreControlled(address(1)) {}

    /// @notice initializer for the proxy storage
    function init(address _core) external {
        assert(address(core()) == address(0));
        _setCore(_core);
    }

    /// -------------------------------------------------------------------------------------
    /// Configuration
    /// -------------------------------------------------------------------------------------

    /// @notice set an address for a given name
    function setAddress(string memory _name, address _address) external onlyCoreRole(CoreRoles.GOVERNOR) {
        addresses[keccak256(abi.encode(_name))] = _address;
        emit AddressSet(block.timestamp, _name, _address);
    }

    /// @notice get an address for a given name
    function getAddress(string memory _name) public view returns (address) {
        return addresses[keccak256(abi.encode(_name))];
    }

    /// @notice manage the whitelist of routers to be used by the zap functions
    function setEnabledRouter(address _router, bool _enabled) external onlyCoreRole(CoreRoles.PROTOCOL_PARAMETERS) {
        enabledRouters[_router] = _enabled;
        emit SetEnabledRouter(block.timestamp, _router, _enabled);
    }

    /// @notice set the fee charged for zaps
    function setZapFee(uint256 _zapFee) external onlyCoreRole(CoreRoles.PROTOCOL_PARAMETERS) {
        require(_zapFee <= 0.01e18, InvalidZapFee()); // cannot set to more than 1%
        zapFee = _zapFee;
        emit ZapFeeSet(block.timestamp, _zapFee);
    }

    /// -------------------------------------------------------------------------------------
    /// User interactions
    /// -------------------------------------------------------------------------------------

    function mint(address _to, uint256 _amount) external whenNotPaused nonReentrant returns (uint256) {
        ERC20 usdc = ERC20(getAddress("USDC"));
        MintController mintController = MintController(getAddress("mintController"));

        usdc.safeTransferFrom(msg.sender, address(this), _amount);
        usdc.approve(address(mintController), _amount);
        return mintController.mint(_to, _amount);
    }

    function mintAndStake(address _to, uint256 _amount) external whenNotPaused nonReentrant returns (uint256) {
        MintController mintController = MintController(getAddress("mintController"));
        StakedToken siusd = StakedToken(getAddress("stakedToken"));
        ReceiptToken iusd = ReceiptToken(getAddress("receiptToken"));
        ERC20 usdc = ERC20(getAddress("USDC"));
        YieldSharingV2 yieldSharing = YieldSharingV2(getAddress("yieldSharing"));

        usdc.safeTransferFrom(msg.sender, address(this), _amount);
        usdc.approve(address(mintController), _amount);
        uint256 receiptTokens = mintController.mint(address(this), _amount);

        yieldSharing.distributeInterpolationRewards();
        yieldSharing.setCanEnterOrExitStakedToken(true);
        iusd.approve(address(siusd), receiptTokens);
        siusd.deposit(receiptTokens, _to);
        yieldSharing.setCanEnterOrExitStakedToken(false);

        return receiptTokens;
    }

    function stake(address _to, uint256 _receiptTokens) external whenNotPaused nonReentrant returns (uint256) {
        StakedToken siusd = StakedToken(getAddress("stakedToken"));
        ReceiptToken iusd = ReceiptToken(getAddress("receiptToken"));
        YieldSharingV2 yieldSharing = YieldSharingV2(getAddress("yieldSharing"));

        // forge-lint: disable-next-line(erc20-unchecked-transfer)
        iusd.transferFrom(msg.sender, address(this), _receiptTokens);
        iusd.approve(address(siusd), _receiptTokens);
        yieldSharing.distributeInterpolationRewards();
        yieldSharing.setCanEnterOrExitStakedToken(true);
        uint256 stakedTokens = siusd.deposit(_receiptTokens, _to);
        yieldSharing.setCanEnterOrExitStakedToken(false);

        return stakedTokens;
    }

    function unstake(address _to, uint256 _stakedTokens) external whenNotPaused nonReentrant returns (uint256) {
        StakedToken siusd = StakedToken(getAddress("stakedToken"));
        YieldSharingV2 yieldSharing = YieldSharingV2(getAddress("yieldSharing"));

        // forge-lint: disable-next-line(erc20-unchecked-transfer)
        siusd.transferFrom(msg.sender, address(this), _stakedTokens);
        yieldSharing.distributeInterpolationRewards();
        yieldSharing.setCanEnterOrExitStakedToken(true);
        uint256 receiptTokens = siusd.redeem(_stakedTokens, _to, address(this));
        yieldSharing.setCanEnterOrExitStakedToken(false);

        return receiptTokens;
    }

    function _zapToReceiptTokens(address _token, uint256 _amount, address _router, bytes calldata _routerData)
        internal
        returns (uint256, ReceiptToken)
    {
        require(enabledRouters[_router], InvalidZapRouter());

        // pull in the tokens and approve the router if not using native ETH
        if (_token != address(0xEeeeeEeeeEeEeeEeEeEeeEEEeeeeEeeeeeeeEEeE)) {
            ERC20(_token).safeTransferFrom(msg.sender, address(this), _amount);
            ERC20(_token).forceApprove(address(_router), _amount);
        }

        // perform swap to USDC
        (bool swapSuccess,) = _router.call{value: msg.value}(_routerData);
        require(swapSuccess, SwapFailed());

        // read the protocol addresses from storage
        MintController mintController = MintController(getAddress("mintController"));
        ERC20 usdc = ERC20(getAddress("USDC"));
        ReceiptToken iusd = ReceiptToken(getAddress("receiptToken"));

        // mint iUSD
        uint256 usdcReceived = usdc.balanceOf(address(this));
        usdc.approve(address(mintController), usdcReceived);
        uint256 receiptTokens = mintController.mint(address(this), usdcReceived);

        {
            uint256 _zapFee = zapFee;
            if (_zapFee != 0) {
                uint256 fee = receiptTokens.mulWadDown(_zapFee);
                receiptTokens -= fee;
                // forge-lint: disable-next-line(erc20-unchecked-transfer)
                iusd.transfer(getAddress("yieldSharing"), fee);
            }
        }

        emit ZapIn(block.timestamp, msg.sender, _token, _amount, receiptTokens);

        return (receiptTokens, iusd);
    }

    function zapIn(address _token, uint256 _amount, address _router, bytes calldata _routerData, address _to)
        external
        payable
        whenNotPaused
        nonReentrant
        returns (uint256)
    {
        (uint256 receiptTokens, ReceiptToken iusd) = _zapToReceiptTokens(_token, _amount, _router, _routerData);

        // send iUSD to receiver
        // forge-lint: disable-next-line(erc20-unchecked-transfer)
        iusd.transfer(_to, receiptTokens);
        return receiptTokens;
    }

    function zapInAndStake(address _token, uint256 _amount, address _router, bytes calldata _routerData, address _to)
        external
        payable
        whenNotPaused
        nonReentrant
        returns (uint256)
    {
        (uint256 receiptTokens, ReceiptToken iusd) = _zapToReceiptTokens(_token, _amount, _router, _routerData);

        // read the protocol addresses from storage
        StakedToken siusd = StakedToken(getAddress("stakedToken"));
        YieldSharingV2 yieldSharing = YieldSharingV2(getAddress("yieldSharing"));

        // mint iUSD and stake it to siUSD
        yieldSharing.distributeInterpolationRewards();
        yieldSharing.setCanEnterOrExitStakedToken(true);
        iusd.approve(address(siusd), receiptTokens);
        siusd.deposit(receiptTokens, _to);
        yieldSharing.setCanEnterOrExitStakedToken(false);
        return receiptTokens;
    }

    function zapInAndLock(
        address _token,
        uint256 _amount,
        address _router,
        bytes calldata _routerData,
        uint32 _unwindingEpochs,
        address _to
    ) external payable whenNotPaused nonReentrant returns (uint256) {
        (uint256 receiptTokens, ReceiptToken iusd) = _zapToReceiptTokens(_token, _amount, _router, _routerData);

        // read the protocol addresses from storage
        LockingController lockingController = LockingController(getAddress("lockingController"));

        // lock the iUSD
        iusd.approve(address(lockingController), receiptTokens);
        lockingController.createPosition(receiptTokens, _unwindingEpochs, _to);
        return receiptTokens;
    }

    function mintAndLock(address _to, uint256 _amount, uint32 _unwindingEpochs)
        external
        whenNotPaused
        nonReentrant
        returns (uint256)
    {
        MintController mintController = MintController(getAddress("mintController"));
        ReceiptToken iusd = ReceiptToken(getAddress("receiptToken"));
        LockingController lockingController = LockingController(getAddress("lockingController"));
        ERC20 usdc = ERC20(getAddress("USDC"));

        usdc.safeTransferFrom(msg.sender, address(this), _amount);
        usdc.approve(address(mintController), _amount);
        uint256 receiptTokens = mintController.mint(address(this), _amount);

        iusd.approve(address(lockingController), receiptTokens);
        lockingController.createPosition(receiptTokens, _unwindingEpochs, _to);
        return receiptTokens;
    }

    function unstakeAndLock(address _to, uint256 _amount, uint32 _unwindingEpochs)
        external
        whenNotPaused
        nonReentrant
        returns (uint256)
    {
        ReceiptToken iusd = ReceiptToken(getAddress("receiptToken"));
        StakedToken siusd = StakedToken(getAddress("stakedToken"));
        LockingController lockingController = LockingController(getAddress("lockingController"));
        YieldSharingV2 yieldSharing = YieldSharingV2(getAddress("yieldSharing"));

        // forge-lint: disable-next-line(erc20-unchecked-transfer)
        siusd.transferFrom(msg.sender, address(this), _amount);
        yieldSharing.distributeInterpolationRewards();
        yieldSharing.setCanEnterOrExitStakedToken(true);
        uint256 receiptTokens = siusd.redeem(_amount, address(this), address(this));
        yieldSharing.setCanEnterOrExitStakedToken(false);

        iusd.approve(address(lockingController), receiptTokens);
        lockingController.createPosition(receiptTokens, _unwindingEpochs, _to);
        return receiptTokens;
    }

    function createPosition(uint256 _amount, uint32 _unwindingEpochs, address _recipient)
        external
        whenNotPaused
        nonReentrant
    {
        ReceiptToken iusd = ReceiptToken(getAddress("receiptToken"));
        LockingController lockingController = LockingController(getAddress("lockingController"));

        // forge-lint: disable-next-line(erc20-unchecked-transfer)
        iusd.transferFrom(msg.sender, address(this), _amount);
        iusd.approve(address(lockingController), _amount);
        lockingController.createPosition(_amount, _unwindingEpochs, _recipient);
    }

    function startUnwinding(uint256 _shares, uint32 _unwindingEpochs) external whenNotPaused nonReentrant {
        LockingController lockingController = LockingController(getAddress("lockingController"));
        LockedPositionToken liusd = LockedPositionToken(lockingController.shareToken(_unwindingEpochs));

        // forge-lint: disable-next-line(erc20-unchecked-transfer)
        liusd.transferFrom(msg.sender, address(this), _shares);
        liusd.approve(address(lockingController), _shares);
        lockingController.startUnwinding(_shares, _unwindingEpochs, msg.sender);
    }

    function increaseUnwindingEpochs(uint32 _oldUnwindingEpochs, uint32 _newUnwindingEpochs, uint256 _shares)
        external
        whenNotPaused
        nonReentrant
    {
        LockingController lockingController = LockingController(getAddress("lockingController"));
        LockedPositionToken liusd = LockedPositionToken(lockingController.shareToken(_oldUnwindingEpochs));

        // forge-lint: disable-next-line(erc20-unchecked-transfer)
        liusd.transferFrom(msg.sender, address(this), _shares);
        liusd.approve(address(lockingController), _shares);
        lockingController.increaseUnwindingEpochs(_shares, _oldUnwindingEpochs, _newUnwindingEpochs, msg.sender);
    }

    function cancelUnwinding(uint256 _unwindingTimestamp, uint32 _newUnwindingEpochs)
        external
        whenNotPaused
        nonReentrant
    {
        LockingController(getAddress("lockingController"))
            .cancelUnwinding(msg.sender, _unwindingTimestamp, _newUnwindingEpochs);
    }

    function withdraw(uint256 _unwindingTimestamp) external whenNotPaused nonReentrant {
        _revertIfThereAreUnaccruedLosses();
        LockingController(getAddress("lockingController")).withdraw(msg.sender, _unwindingTimestamp);
    }

    function withdraw(address _user, uint256 _unwindingTimestamp) external whenNotPaused nonReentrant {
        _revertIfThereAreUnaccruedLosses();
        LockingController(getAddress("lockingController")).withdraw(_user, _unwindingTimestamp);
    }

    function redeem(address _to, uint256 _amount, uint256 _minAssetsOut)
        external
        whenNotPaused
        nonReentrant
        returns (uint256)
    {
        _revertIfThereAreUnaccruedLosses();
        ReceiptToken iusd = ReceiptToken(getAddress("receiptToken"));
        RedeemController redeemController = RedeemController(getAddress("redeemController"));

        // forge-lint: disable-next-line(erc20-unchecked-transfer)
        iusd.transferFrom(msg.sender, address(this), _amount);
        iusd.approve(address(redeemController), _amount);
        uint256 assetsOut = redeemController.redeem(_to, _amount);
        require(assetsOut >= _minAssetsOut, MinAssetsOutError(_minAssetsOut, assetsOut));
        return assetsOut;
    }

    function claimRedemption() external whenNotPaused nonReentrant {
        RedeemController(getAddress("redeemController")).claimRedemption(msg.sender);
    }

    function vote(
        address _asset,
        uint32 _unwindingEpochs,
        AllocationVoting.AllocationVote[] calldata _liquidVotes,
        AllocationVoting.AllocationVote[] calldata _illiquidVotes
    ) external whenNotPaused nonReentrant {
        AllocationVoting(getAddress("allocationVoting"))
            .vote(msg.sender, _asset, _unwindingEpochs, _liquidVotes, _illiquidVotes);
    }

    function multiVote(
        address[] calldata _assets,
        uint32[] calldata _unwindingEpochs,
        AllocationVoting.AllocationVote[][] calldata _liquidVotes,
        AllocationVoting.AllocationVote[][] calldata _illiquidVotes
    ) external whenNotPaused nonReentrant {
        AllocationVoting allocationVoting = AllocationVoting(getAddress("allocationVoting"));

        for (uint256 i = 0; i < _assets.length; i++) {
            allocationVoting.vote(msg.sender, _assets[i], _unwindingEpochs[i], _liquidVotes[i], _illiquidVotes[i]);
        }
    }

    function _revertIfThereAreUnaccruedLosses() internal view {
        YieldSharingV2 yieldSharing = YieldSharingV2(getAddress("yieldSharing"));
        require(yieldSharing.unaccruedYield() >= 0, PendingLossesUnapplied());
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {CoreRoles} from "@libraries/CoreRoles.sol";
import {InfiniFiCore} from "@core/InfiniFiCore.sol";

/// @notice Defines some modifiers and utilities around interacting with Core
abstract contract CoreControlled is Pausable {
    error UnderlyingCallReverted(bytes returnData);

    /// @notice emitted when the reference to core is updated
    event CoreUpdate(address indexed oldCore, address indexed newCore);

    /// @notice reference to Core
    InfiniFiCore private _core;

    constructor(address coreAddress) {
        _core = InfiniFiCore(coreAddress);
    }

    /// @notice named onlyCoreRole to prevent collision with OZ onlyRole modifier
    modifier onlyCoreRole(bytes32 role) {
        require(_core.hasRole(role, msg.sender), "UNAUTHORIZED");
        _;
    }

    /// @notice address of the Core contract referenced
    function core() public view returns (InfiniFiCore) {
        return _core;
    }

    /// @notice WARNING CALLING THIS FUNCTION CAN POTENTIALLY
    /// BRICK A CONTRACT IF CORE IS SET INCORRECTLY
    /// @notice set new reference to core
    /// only callable by governor
    /// @param newCore to reference
    function setCore(address newCore) external onlyCoreRole(CoreRoles.GOVERNOR) {
        _setCore(newCore);
    }

    /// @notice WARNING CALLING THIS FUNCTION CAN POTENTIALLY
    /// BRICK A CONTRACT IF CORE IS SET INCORRECTLY
    /// @notice set new reference to core
    /// @param newCore to reference
    function _setCore(address newCore) internal {
        address oldCore = address(_core);
        _core = InfiniFiCore(newCore);

        emit CoreUpdate(oldCore, newCore);
    }

    /// @notice set pausable methods to paused
    function pause() public onlyCoreRole(CoreRoles.PAUSE) {
        _pause();
    }

    /// @notice set pausable methods to unpaused
    function unpause() public onlyCoreRole(CoreRoles.UNPAUSE) {
        _unpause();
    }

    /// ------------------------------------------
    /// ------------ Emergency Action ------------
    /// ------------------------------------------

    /// inspired by MakerDAO Multicall:
    /// https://github.com/makerdao/multicall/blob/master/src/Multicall.sol

    /// @notice struct to pack calldata and targets for an emergency action
    struct Call {
        /// @notice target address to call
        address target;
        /// @notice amount of eth to send with the call
        uint256 value;
        /// @notice payload to send to target
        bytes callData;
    }

    /// @notice due to inflexibility of current smart contracts,
    /// add this ability to be able to execute arbitrary calldata
    /// against arbitrary addresses.
    /// callable only by governor
    function emergencyAction(Call[] calldata calls)
        external
        payable
        virtual
        onlyCoreRole(CoreRoles.GOVERNOR)
        returns (bytes[] memory returnData)
    {
        returnData = new bytes[](calls.length);
        for (uint256 i = 0; i < calls.length; i++) {
            address payable target = payable(calls[i].target);
            uint256 value = calls[i].value;
            bytes calldata callData = calls[i].callData;

            (bool success, bytes memory returned) = target.call{value: value}(callData);
            require(success, UnderlyingCallReverted(returned));
            returnData[i] = returned;
        }
    }
}

